use std::collections::HashMap;

fn two_sum(nums: Vec<i32>, target: i32) -> Option<(usize, usize)> {
    // Map value -> earliest index where it appears
    let mut first_idx: HashMap<i32, usize> = HashMap::new();

    for (j, &x) in nums.iter().enumerate() {
        // Need y + x == target  => y == target - x
        // If subtraction overflows i32, no y can satisfy within i32.
        if let Some(y) = target.checked_sub(x) {
            if let Some(&i) = first_idx.get(&y) {
                // i < j holds because we only insert indices < current j.
                // Also, y + x cannot overflow because it equals target (an i32).
                return Some((i, j));
            }
        }

        // Keep the earliest index for each value to ensure lexicographically smallest.
        first_idx.entry(x).or_insert(j);
    }

    None
}